package applehealth

import (
	"bufio"
	"encoding/json"
	"os"
	"testing"

	"github.com/soma-intelligence/open-health-sync/internal/model"
)

// TestIOSUploadContract maps lines produced by the iOS client's own encoder
// (the SDK's UploadRecord.line()) and checks each lands where
// the client means it to. testdata/ios_upload_lines.ndjson is generated by that
// encoder, not written by hand: when the client's line format changes,
// regenerate the file from it and this test says whether this connector still agrees.
func TestIOSUploadContract(t *testing.T) {
	f, err := os.Open("testdata/ios_upload_lines.ndjson")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	m := New()
	var results []*resultLine
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		var record map[string]any
		if err := json.Unmarshal(scanner.Bytes(), &record); err != nil {
			t.Fatalf("line does not parse: %v", err)
		}
		res, err := m.mapRecord(record, "11111111-1111-1111-1111-111111111111")
		if err != nil {
			t.Fatalf("map %v: %v", record, err)
		}
		if res == nil || res.IsEmpty() {
			t.Fatalf("line dropped by the mapper: %s", scanner.Text())
		}
		results = append(results, &resultLine{res: res})
	}
	if len(results) != 7 {
		t.Fatalf("mapped %d lines, want 7", len(results))
	}

	hr := results[0].res.QuantitySamples
	if len(hr) != 1 || hr[0].Unit != "bpm" || hr[0].Value != 72.5 {
		t.Fatalf("heart rate = %+v", hr)
	}
	if hr[0].SourceBundleID != "com.apple.health.ABC" || hr[0].ProductType != "Watch7,1" || hr[0].DeviceModel != "Watch" {
		t.Fatalf("provenance lost: bundle %q product %q model %q", hr[0].SourceBundleID, hr[0].ProductType, hr[0].DeviceModel)
	}
	if hr[0].WasUserEntered == nil || *hr[0].WasUserEntered {
		t.Fatalf("wasUserEntered = %v", hr[0].WasUserEntered)
	}

	spo2 := results[1].res.QuantitySamples
	if len(spo2) != 1 || spo2[0].Value != 0.97 {
		t.Fatalf("oxygen saturation must stay a 0..1 fraction: %+v", spo2)
	}

	steps := results[2].res.QuantitySamples
	if len(steps) != 1 || steps[0].Value != 120 || steps[0].EndDate.Sub(steps[0].StartDate).Seconds() != 60 {
		t.Fatalf("steps = %+v", steps)
	}

	if len(results[3].res.SleepSessions) != 1 {
		t.Fatalf("in-bed line must make a sleep session: %+v", results[3].res)
	}
	phases := results[4].res.SleepPhases
	if len(phases) != 1 || phases[0].Phase != "deep" {
		t.Fatalf("deep sleep phase = %+v", phases)
	}

	workouts := results[5].res.Workouts
	if len(workouts) != 1 {
		t.Fatalf("workout = %+v", results[5].res)
	}
	w := workouts[0]
	if w.ActiveEnergyKcal == nil || *w.ActiveEnergyKcal != 200 || w.DistanceM == nil || *w.DistanceM != 2000.5 {
		t.Fatalf("workout totals = energy %v distance %v", w.ActiveEnergyKcal, w.DistanceM)
	}

	bp := results[6].res.QuantitySamples
	if len(bp) != 2 {
		t.Fatalf("blood pressure must give systolic and diastolic: %+v", results[6].res)
	}
	values := map[float64]bool{bp[0].Value: true, bp[1].Value: true}
	if !values[110] || !values[70] {
		t.Fatalf("blood pressure values = %v", values)
	}
}

type resultLine struct{ res *model.MapResult }
